package ec.cityalerta.app.viewmodelimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport ec.cityalerta.app.model.data.reporte.ReporteEstadoimport ec.cityalerta.app.model.data.reporte.ReporteSearchResultimport ec.cityalerta.app.model.data.reporte.ReportTypeimport ec.cityalerta.app.model.repository.ReporteRepositoryimport ec.cityalerta.app.model.repository.ReporteImagenRepositoryimport ec.cityalerta.app.model.repository.ReporteStorageRepositoryimport ec.cityalerta.app.model.repository.PerfilRepositoryimport ec.cityalerta.app.model.data.contracts.auth.AuthRepositoryContractimport ec.cityalerta.app.model.remote.SupabaseProviderimport io.github.jan.supabase.gotrue.authimport kotlinx.coroutines.Jobimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.launchimport java.time.Instantimport java.time.temporal.ChronoUnitprivate const val TIME_AGO_RECENT = "Hace poco"// Estado de la pantalla de busqueda de reportesdata class SearchReportState(    val isLoading: Boolean = false,    val searchQuery: String = "",    val selectedCategory: ReportType? = null,    val reportes: List<ReporteUI> = emptyList(),    val error: String? = null,    val ciudadId: String = "")// ViewModel que maneja la busqueda y filtrado de reportesclass SearchReportViewModel(    private val authRepository: AuthRepositoryContract,    private val reporteRepository: ReporteRepository = ReporteRepository(),    private val reporteImagenRepository: ReporteImagenRepository = ReporteImagenRepository(),    private val reporteStorageRepository: ReporteStorageRepository = ReporteStorageRepository(),    private val perfilRepository: PerfilRepository = PerfilRepository()) : ViewModel() {    private val _state = MutableStateFlow(SearchReportState())    val state: StateFlow<SearchReportState> = _state    private var dataLoaded = false    private var searchJob: Job? = null    // Carga los datos cuando el usuario entra a la pantalla de busqueda    fun loadData(force: Boolean = false) {        if (!force && dataLoaded && _state.value.reportes.isNotEmpty()) return        initializeCiudadId()    }    // Inicializa el ID de la ciudad desde el perfil del usuario autenticado    private fun initializeCiudadId() {        viewModelScope.launch {            try {                val userId = authRepository.getUserId().getOrNull()                if (userId != null) {                    val perfil = perfilRepository.getById(userId).getOrNull()                    perfil?.let {                        _state.value = _state.value.copy(ciudadId = it.ciudadId)                        search("")                        dataLoaded = true                    }                }            } catch (_: Exception) {                _state.value = _state.value.copy(error = "Error al cargar ciudad")            }        }    }    fun updateSearchQuery(query: String) {        _state.value = _state.value.copy(searchQuery = query)                searchJob?.cancel()        searchJob = viewModelScope.launch {            delay(500)            search(query)        }    }    fun selectCategory(category: ReportType?) {        _state.value = _state.value.copy(selectedCategory = category)        searchJob?.cancel()        search(_state.value.searchQuery)    }    private fun search(query: String) {        viewModelScope.launch {            _state.value = _state.value.copy(isLoading = true, error = null)            try {                val ciudadId = _state.value.ciudadId                if (ciudadId.isEmpty()) {                    _state.value = _state.value.copy(isLoading = false, error = "No se pudo cargar la ciudad")                    return@launch                }                val results = reporteRepository.searchReportes(                    ciudadId = ciudadId,                    categoria = _state.value.selectedCategory,                    barrioNombreQuery = query.takeIf { it.isNotBlank() }                ).getOrNull().orEmpty()                val reportesUI = mapSearchResultsToUi(results)                _state.value = _state.value.copy(                    isLoading = false,                    reportes = reportesUI                )            } catch (e: Exception) {                _state.value = _state.value.copy(                    isLoading = false,                    error = e.message ?: "Error en la busqueda"                )            }        }    }    private suspend fun mapSearchResultsToUi(results: List<ReporteSearchResult>): List<ReporteUI> {        if (results.isEmpty()) return emptyList()        val reporteIds = results.map { it.reporte.id }        val imagenes = reporteImagenRepository            .getFirstImagenesByReporteIds(reporteIds)            .getOrNull()            .orEmpty()        val storagePaths = imagenes.values            .mapNotNull { it.storage_uuid.takeIf(String::isNotBlank) }            .distinct()        val signedUrls = reporteStorageRepository            .generateSignedImageUrls(storagePaths)            .getOrNull()            .orEmpty()        return results.map { result ->            val imagen = imagenes[result.reporte.id]            val imageUrl = imagen?.storage_uuid?.takeIf { it.isNotBlank() }?.let { signedUrls[it] }            ReporteUI(                id = result.reporte.id,                categoria = mapCategoriaLabel(result.reporte.categoria),                categoryType = result.reporte.categoria,                imageUrl = imageUrl,                barrio = result.barrioNombre.ifBlank { "Barrio desconocido" },                direccion = result.direccionAproximada ?: "Direccion no disponible",                descripcion = result.reporte.descripcion,                estado = mapEstadoLabel(result.reporte.estado),                fecha = result.reporte.fecha_reporte,                timeAgo = calculateTimeAgo(result.reporte.created_at),                lat = 0.0,                lng = 0.0            )        }    }    private fun calculateTimeAgo(createdAt: String?): String {        if (createdAt.isNullOrBlank()) return TIME_AGO_RECENT        return try {            val createdAtInstant = Instant.parse(createdAt)            val now = Instant.now()            val minutes = ChronoUnit.MINUTES.between(createdAtInstant, now)            val hours = ChronoUnit.HOURS.between(createdAtInstant, now)            val days = ChronoUnit.DAYS.between(createdAtInstant, now)            when {                days > 0 -> "Hace $days dia${if (days > 1) "s" else ""}"                hours > 0 -> "Hace $hours hora${if (hours > 1) "s" else ""}"                minutes > 0 -> "Hace $minutes minuto${if (minutes > 1) "s" else ""}"                else -> TIME_AGO_RECENT            }        } catch (_: Exception) {            TIME_AGO_RECENT        }    }    // Convierte el tipo de categoria a etiqueta legible    private fun mapCategoriaLabel(categoria: ReportType): String = when (categoria) {        ReportType.ZONA_DE_RIESGO -> "Seguridad"        ReportType.BACHE -> "Bache"        ReportType.AGUA -> "Agua"        ReportType.LUZ -> "Luz"    }    // Convierte el estado del reporte a etiqueta legible    private fun mapEstadoLabel(estado: ReporteEstado): String = when (estado) {        ReporteEstado.PENDIENTE -> "Pendiente"        ReporteEstado.EN_PROCESO -> "En Proceso"        ReporteEstado.RESUELTO -> "Resuelto"    }}